// Each bounded context becomes a self-contained package/service.
// The Order context knows nothing about how Inventory models a product.
package order

// Order is the aggregate root of the Order bounded context.
type Order struct {
	ID         string
	CustomerID string    // just an ID reference across the boundary
	Lines      []Line    // owned entities inside this context
	Status     Status
}

type Line struct {
	SKU      string // an opaque reference; NOT a shared Product struct
	Quantity int
}

// The context exposes behavior, not raw data, across its boundary.
func (o *Order) Confirm() error {
	if len(o.Lines) == 0 {
		return ErrEmptyOrder
	}
	o.Status = StatusConfirmed
	return nil
}

// The store layer is the ONLY code that touches this service's DB.
// Other services never import this package or share its connection.
package store

import (
	"context"
	"database/sql"
)

// OrderStore owns the orders schema; it is private to the order service.
type OrderStore struct {
	db *sql.DB // this service's OWN database, not a shared one
}

func (s *OrderStore) Save(ctx context.Context, o Order) error {
	_, err := s.db.ExecContext(ctx,
		`INSERT INTO orders (id, customer_id, status) VALUES ($1,$2,$3)`,
		o.ID, o.CustomerID, o.Status)
	return err // callers get data via the API, never via this table
}

// Anti-pattern: nanoservices split by entity, coupled at runtime.
//   order-service -> line-item-service -> price-service -> tax-service
// One user action fans out into a synchronous call chain.

// Better: one Order service owns the whole ordering capability.
package order

type Service struct {
	store  *store.OrderStore
	prices PriceCatalog // an interface, resolved in-process, not an RPC
}

// A single cohesive operation, no cross-service chatter for one action.
func (s *Service) Place(ctx context.Context, o Order) error {
	if err := o.Confirm(); err != nil {
		return err
	}
	return s.store.Save(ctx, o)
}

// Commit local state, then publish an event; consumers converge later.
package order

type OrderPlaced struct {
	OrderID    string
	CustomerID string
	TotalCents int64
}

type Publisher interface {
	Publish(ctx context.Context, e OrderPlaced) error
}

func (s *Service) Place(ctx context.Context, o Order, pub Publisher) error {
	if err := s.store.Save(ctx, o); err != nil {
		return err // local transaction is the source of truth
	}
	// Inventory & Billing subscribe; they update eventually, not now.
	return pub.Publish(ctx, OrderPlaced{OrderID: o.ID, CustomerID: o.CustomerID})
}

// Directory layout for a single Go microservice:
//
//   order-service/
//     cmd/
//       server/main.go        // wires everything, starts the server
//     internal/
//       order/                 // DOMAIN: entities + business rules
//         service.go
//       transport/http/        // TRANSPORT: HTTP handlers -> service
//         handler.go
//       store/postgres/        // STORE: DB adapter implementing Repo
//         order_store.go
//
// Domain defines the port; store provides the adapter.
package order

import "context"

type Repository interface {
	Save(ctx context.Context, o Order) error
	Get(ctx context.Context, id string) (Order, error)
} // implemented in internal/store/postgres, injected into Service

// A modular monolith: bounded contexts as PACKAGES, one binary.
// You get clean seams now, and can extract a service later.
package main

import (
	"myapp/internal/billing"
	"myapp/internal/inventory"
	"myapp/internal/order"
)

func main() {
	// Contexts talk through interfaces, resolved in-process (a func call,
	// not a network hop). If order/ later needs its own DB and pipeline,
	// the interface boundary is where you'd cut it into a service.
	inv := inventory.NewService()
	bill := billing.NewService()
	ord := order.NewService(inv, bill) // in-process dependency injection
	_ = ord
}

