package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
)

// ---- domain (internal/order): business logic + the port it needs ----
type Order struct {
	ID         string `json:"id"`
	CustomerID string `json:"customer_id"`
}

var ErrNotFound = errors.New("order not found")

// Repository is the PORT the domain depends on (defined here, not in store).
type Repository interface {
	Get(ctx context.Context, id string) (Order, error)
}

type Service struct{ repo Repository }

func (s *Service) Fetch(ctx context.Context, id string) (Order, error) {
	if id == "" {
		return Order{}, errors.New("empty id")
	}
	return s.repo.Get(ctx, id) // domain only knows the interface
}

// ---- store (internal/store): the ADAPTER implementing the port ----
type memStore struct{ m map[string]Order }

func (s memStore) Get(_ context.Context, id string) (Order, error) {
	o, ok := s.m[id]
	if !ok {
		return Order{}, ErrNotFound
	}
	return o, nil
}

// ---- transport (internal/transport/http): adapts HTTP -> domain ----
type Handler struct{ svc *Service }

func (h Handler) get(w http.ResponseWriter, r *http.Request) {
	o, err := h.svc.Fetch(r.Context(), r.PathValue("id"))
	if errors.Is(err, ErrNotFound) {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	_ = json.NewEncoder(w).Encode(o)
}

func main() {
	// cmd/server: wire adapters into the domain (dependency injection).
	store := memStore{m: map[string]Order{"42": {ID: "42", CustomerID: "c1"}}}
	h := Handler{svc: &Service{repo: store}}
	o, _ := h.svc.Fetch(context.Background(), "42")
	fmt.Printf("%+v\n", o)
}

package main

import (
	"context"
	"fmt"
)

// The Order context references the customer by ID only.
type Order struct {
	ID         string
	CustomerID string // opaque reference across the boundary
	TotalCents int64
}

// CustomerClient is how THIS service talks to the Customer service:
// a narrow interface returning only the fields we actually need.
type CustomerClient interface {
	DisplayName(ctx context.Context, id string) (string, error)
}

// A fake client stands in for an HTTP/gRPC call to the Customer service.
type fakeCustomers struct{}

func (fakeCustomers) DisplayName(_ context.Context, id string) (string, error) {
	return "Ada (" + id + ")", nil // would be a network call in production
}

func receipt(ctx context.Context, o Order, cc CustomerClient) (string, error) {
	name, err := cc.DisplayName(ctx, o.CustomerID) // fetch across boundary
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("Order %s for %s: $%.2f", o.ID, name, float64(o.TotalCents)/100), nil
}

func main() {
	o := Order{ID: "42", CustomerID: "c1", TotalCents: 1999}
	r, _ := receipt(context.Background(), o, fakeCustomers{})
	fmt.Println(r)
}

package main

import (
	"context"
	"errors"
	"fmt"
)

type Order struct {
	ID         string
	CustomerID string
	TotalCents int64
}

type OrderPlaced struct {
	OrderID    string
	CustomerID string
	TotalCents int64
}

type Store interface {
	Save(ctx context.Context, o Order) error
}
type Publisher interface {
	Publish(ctx context.Context, e OrderPlaced) error
}

type Service struct {
	store Store
	bus   Publisher
}

// Place commits locally FIRST, then publishes so Billing/Inventory converge.
func (s *Service) Place(ctx context.Context, o Order) error {
	if err := s.store.Save(ctx, o); err != nil {
		return fmt.Errorf("save order: %w", err) // no event on failure
	}
	return s.bus.Publish(ctx, OrderPlaced{
		OrderID: o.ID, CustomerID: o.CustomerID, TotalCents: o.TotalCents,
	})
}

// --- fakes to make it runnable ---
type memStore struct{}

func (memStore) Save(context.Context, Order) error { return nil }

type logBus struct{}

func (logBus) Publish(_ context.Context, e OrderPlaced) error {
	if e.OrderID == "" {
		return errors.New("missing id")
	}
	fmt.Printf("event OrderPlaced: order=%s total=%d\n", e.OrderID, e.TotalCents)
	return nil
}

func main() {
	svc := &Service{store: memStore{}, bus: logBus{}}
	_ = svc.Place(context.Background(), Order{ID: "42", CustomerID: "c1", TotalCents: 1999})
}

