package decompose

type Candidate struct {
	DistinctBoundedContext  bool
	NeedsIndependentScale   bool
	SeparateTeam            bool
	AlwaysDeploysWithCaller bool
}

// ShouldExtract applies the boundary decision framework.
func ShouldExtract(c Candidate) (bool, string) {
	if !c.DistinctBoundedContext {
		return false, "not a distinct bounded context: keep it in the monolith"
	}
	if c.AlwaysDeploysWithCaller {
		return false, "always deploys with its caller: extracting yields a distributed monolith"
	}
	if !c.NeedsIndependentScale && !c.SeparateTeam {
		return false, "no scaling or team-autonomy pressure: a module is cheaper than a service"
	}
	return true, "distinct context with real scale/team pressure and independent deploy: extract it"
}

codeLab.testHarness:
package decompose

import "testing"

func TestShouldExtract(t *testing.T) {
	cases := []struct {
		name string
		c    Candidate
		want bool
	}{
		{"good candidate", Candidate{true, true, false, false}, true},
		{"team autonomy only", Candidate{true, false, true, false}, true},
		{"couples deploy", Candidate{true, true, true, true}, false},
		{"not a context", Candidate{false, true, true, false}, false},
		{"no pressure", Candidate{true, false, false, false}, false},
	}
	for _, tc := range cases {
		got, reason := ShouldExtract(tc.c)
		if got != tc.want {
			t.Fatalf("%s: got %v (%q) want %v", tc.name, got, reason, tc.want)
		}
		if reason == "" {
			t.Fatalf("%s: expected a non-empty reason", tc.name)
		}
	}
}

