// order-service owns ONLY its data and publishes an event; it never
// touches billing's tables and never blocks on billing in the hot path.
func (s *OrderService) Place(ctx context.Context, o Order) error {
	// 1) Commit our OWN data — the source of truth for the order.
	if err := s.orders.Save(ctx, o); err != nil {
		return fmt.Errorf("save order: %w", err)
	}
	// 2) Publish an event; Billing consumes it asynchronously and creates
	//    its own invoice in its OWN database. Order stays up if Billing is down.
	return s.bus.Publish(ctx, OrderPlaced{OrderID: o.ID, Cents: o.TotalCents})
}

// billing-service (separate binary + separate DB) reacts to the event:
func (b *BillingService) OnOrderPlaced(ctx context.Context, e OrderPlaced) error {
	return b.invoices.Create(ctx, Invoice{OrderID: e.OrderID, Cents: e.Cents})
}
// For reliability, Save + enqueue the event in the same local transaction
// (the outbox pattern) so the commit and the event can never diverge.

type Candidate struct {
	DistinctBoundedContext  bool // coherent business capability?
	NeedsIndependentScale   bool // hot path that must scale alone?
	SeparateTeam            bool // owned end-to-end by another team?
	AlwaysDeploysWithCaller bool // must ship in lockstep with its caller?
}

// ShouldExtract returns (extract?, reason) using the boundary framework.
func ShouldExtract(c Candidate) (bool, string) {
	if !c.DistinctBoundedContext {
		return false, "not a distinct bounded context: keep it in the monolith"
	}
	if c.AlwaysDeploysWithCaller {
		return false, "couples deploy with caller: extracting yields a distributed monolith"
	}
	if !c.NeedsIndependentScale && !c.SeparateTeam {
		return false, "no scale or team-autonomy pressure: a module beats a service"
	}
	return true, "distinct context, independent deploy, real pressure: extract it"
}
